Tool response:
Tool: calculate_renewal_eligibility
Description: Calculate renewal eligibility for certificants in the 'Certified Data Analyst' program for the current renewal cycle ending 2025-12-31. Returns a report of those who are eligible vs. not eligible based on meeting the required continuing education credits.
Parameters:
    {
      "type": "object",
      "properties": {
        "program_name": {
          "type": "string",
          "description": "Name of the program to check eligibility for",
          "title": "Program Name"
        },
        "renewal_cycle_end_date": {
          "type": "string",
          "description": "End date of the renewal cycle (format: YYYY-MM-DD)",
          "title": "Renewal Cycle End Date"
        }
      },
      "required": [
        "program_name",
        "renewal_cycle_end_date"
      ]
    }
